func _initialize() -> void:
	for m in ["hero_caster", "crab_armored", "keeper_house", "lighthouse"]:
		var n := (load("res://assets/models/%s.glb" % m) as PackedScene).instantiate() as Node3D
		root.add_child(n)
		var all := _aabb(n, Transform3D.IDENTITY)
		print("MEASURE %s min=%s max=%s h=%.2f" % [m, all.position, all.end, all.size.y])
		for c in n.find_children("*", "MeshInstance3D", true, false):
			var a := _aabb(c, Transform3D.IDENTITY)
			var nm := str(c.name)
			if "door" in nm.to_lower() or "Door" in nm or "KH_" in nm or "LH_" in nm:
				print("  %s min=%s max=%s" % [nm, a.position, a.end])
	quit(0)

func _aabb(n: Node, t: Transform3D) -> AABB:
	var res := AABB()
	var first := true
	var xf := t
	if n is Node3D:
		xf = t * (n as Node3D).transform
	if n is MeshInstance3D and (n as Node3D).visible:
		res = xf * (n as MeshInstance3D).get_aabb()
		first = false
	for c in n.get_children():
		var b := _aabb(c, xf)
		if b.size == Vector3.ZERO:
			continue
		if first:
			res = b
			first = false
		else:
			res = res.merge(b)
	return res

