## Реплей collide_dash: герой упирается в лодку, дом, маяк и обрыв и ни на одном тике не заходит в коллайдер.
func test_collide_replay_never_inside_and_touches_all() -> void:
	var rep := Sim.load_json("res://tests/replays/collide_dash.replay.json")
	var touched := {}
	var worst := [1e9]
	var check := func(s: RefCounted) -> void:
		var p: Vector2 = s.state.player["pos"]
		var r := float(s.bal["player"]["radius"])
		for c in s.state.level["colliders"]:
			var ctr := Vector2(float(c["x"]), float(c["y"]))
			var gap := 0.0
			if c["kind"] == "circle":
				gap = (p - ctr).length() - float(c["r"]) - r
			else:
				var rel := (p - ctr).abs() - Vector2(float(c["hx"]), float(c["hy"]))
				gap = Vector2(maxf(rel.x, 0.0), maxf(rel.y, 0.0)).length() + minf(maxf(rel.x, rel.y), 0.0) - r
			worst[0] = minf(worst[0], gap)
			if gap < 0.001:
				touched[c["id"]] = true
	Sim.run_replay(rep, check)
	assert_gte(worst[0], -0.001, "ни на одном тике герой не внутри коллайдера")
	for id in ["boat", "keeper_house", "lighthouse", "cliff_n"]:
		assert_true(touched.has(id), "реплей упёрся в %s" % id)


